mapper.select:
select count(1)
from ai_call_log
where model_id = #{modelId}

select count(1)
from ai_call_log
where model_id = #{modelId}
  and status = #{status}

select
    count(1) as totalCalls,
    coalesce(sum(case when status = 'SUCCESS' then 1 else 0 end), 0) as successCalls,
    coalesce(sum(case when status = 'FAILED' then 1 else 0 end), 0) as failedCalls,
    0.0 as avgResponseTime,
    0 as totalTokens
from ai_call_log


        and model_id = #{modelId}


        and task_type = #{taskType}


        and created_at >= #{startTime}


        and created_at <= #{endTime}

select
    null as modelId,
    null as modelName,
    count(1) as totalCalls,
    coalesce(sum(case when status = 'SUCCESS' then 1 else 0 end), 0) as successCalls,
    0.0 as successRate
from ai_call_log


        and model_id = #{modelId}


        and task_type = #{taskType}


        and created_at >= #{startTime}


        and created_at <= #{endTime}

select
    null as modelId,
    null as modelName,
    coalesce(avg(response_time), 0) as avgResponseTime,
    coalesce(min(response_time), 0) as minResponseTime,
    coalesce(max(response_time), 0) as maxResponseTime
from ai_call_log


        and model_id = #{modelId}


        and task_type = #{taskType}


        and created_at >= #{startTime}


        and created_at <= #{endTime}

select model_id as modelId, null as modelName, count(1) as callCount, 0 as totalTokens from ai_call_log
and created_at >= #{startTime}
and created_at <= #{endTime}
group by model_id
